const SAVE_KEY = "nemo1732_v045_save";
const LEGACY_SAVE_KEYS = ["nemo1732_v044_save","nemo1732_v042_save","nemo1732_v040_save","nemo1732_v034_save","nemo1732_v033_save","nemo1732_v032_save","nemo1732_v031_save","nemo1732_v03_save","nemo1732_v02_save"];
const MAIN_CLEAR_KEY = "nemo1732_main_cleared";

